# JS-flavored problem adapted with an explicit get/set node API.
class Node:
    def __init__(self, src, parent=None):
        self.src, self.parent = src, parent
        self.dirty = False
        self.changes = {}
        self.kids = {}
    def get(self, k):
        if k in self.changes:
            return self.changes[k]
        if k in self.kids:
            return self.kids[k]
        v = self.src[k]
        if isinstance(v, (dict, list)):
            n = Node(v, self)
            self.kids[k] = n
            return n
        return v
    def set(self, k, v):
        if isinstance(v, Node):
            v = v.raw()
        self.changes[k] = v
        self.kids.pop(k, None)
        self._mark()
    def _mark(self):
        if self.dirty:
            return
        self.dirty = True
        if self.parent:
            self.parent._mark()
    def raw(self):
        if not self.dirty:
            return self.src
        out = list(self.src) if isinstance(self.src, list) else dict(self.src)
        for k, v in self.changes.items():
            out[k] = v
        for k, n in self.kids.items():
            if k not in self.changes:
                out[k] = n.raw()
        return out
class ImmutableHelper:
    def __init__(self, obj):
        self.root = Node(obj)
    def produce(self, mutator):
        mutator(self.root)
        return self.root.raw()

