// Adapted to an explicit get/set node API (C++ has no proxies).
#include <map>
#include <string>
#include <vector>
#include <memory>
using Json = std::map<std::string, double>; // illustrative payload type
class Node {
public:
    Json* src; Node* parent; bool dirty = false;
    std::map<std::string,double> changes;
    std::map<std::string,std::shared_ptr<Node>> kids;
    Node(Json* s, Node* p = nullptr) : src(s), parent(p) {}
    double get(const std::string& k) {
        auto it = changes.find(k);
        if (it != changes.end()) return it->second;
        return (*src)[k];
    }
    void set(const std::string& k, double v) {
        changes[k] = v;
        kids.erase(k);
        mark();
    }
    void mark() {
        if (dirty) return;
        dirty = true;
        if (parent) parent->mark();
    }
    Json raw() {
        if (!dirty) return *src;
        Json out = *src;
        for (auto& kv : changes) out[kv.first] = kv.second;
        return out;
    }
};

