// Adapted to an explicit get/set node API (Java has no proxies).
import java.util.*;
class Node {
    Map<String,Object> src; Node parent;
    boolean dirty = false;
    Map<String,Object> changes = new HashMap<>();
    Map<String,Node> kids = new HashMap<>();
    Node(Map<String,Object> src, Node parent) { this.src = src; this.parent = parent; }
    Object get(String k) {
        if (changes.containsKey(k)) return changes.get(k);
        if (kids.containsKey(k)) return kids.get(k);
        Object v = src.get(k);
        if (v instanceof Map) {
            Node n = new Node((Map<String,Object>) v, this);
            kids.put(k, n);
            return n;
        }
        return v;
    }
    void set(String k, Object v) {
        if (v instanceof Node) v = ((Node) v).raw();
        changes.put(k, v);
        kids.remove(k);
        mark();
    }
    private void mark() {
        if (dirty) return;
        dirty = true;
        if (parent != null) parent.mark();
    }
    @SuppressWarnings("unchecked")
    Object raw() {
        if (!dirty) return src;
        Map<String,Object> out = new HashMap<>(src);
        out.putAll(changes);
        for (Map.Entry<String,Node> e : kids.entrySet())
            if (!changes.containsKey(e.getKey())) out.put(e.getKey(), e.getValue().raw());
        return out;
    }
}
class ImmutableHelper {
    private final Node root;
    ImmutableHelper(Map<String,Object> obj) { root = new Node(obj, null); }
    Object produce(java.util.function.Consumer<Node> mutator) {
        mutator.accept(root);
        return root.raw();
    }
}

