class N {
    constructor(src, parent) {
        this.src = src; this.parent = parent;
        this.dirty = false; this.ch = {}; this.kids = {};
        const node = this;
        this.proxy = new Proxy(src, {
            get(t, p) {
                if (p === '__node') return node;
                return node.get(p);
            },
            set(t, p, v) { node.set(p, v); return true; }
        });
    }
    get(k) {
        if (k in this.ch) return this.ch[k];
        if (k in this.kids) return this.kids[k].proxy;
        const v = this.src[k];
        if (v && typeof v === 'object') {
            const n = new N(v, this);
            this.kids[k] = n;
            return n.proxy;
        }
        return v;
    }
    set(k, v) {
        while (v && v.__node) v = v.__node.raw();
        this.ch[k] = v;
        delete this.kids[k];
        this.mark();
    }
    mark() {
        if (this.dirty) return;
        this.dirty = true;
        if (this.parent) this.parent.mark();
    }
    raw() {
        if (!this.dirty) return this.src;
        const out = Array.isArray(this.src) ? this.src.slice() : Object.assign({}, this.src);
        for (const k in this.ch) out[k] = this.ch[k];
        for (const k in this.kids) if (!(k in this.ch)) out[k] = this.kids[k].raw();
        return out;
    }
}
var ImmutableHelper = function(obj) {
    this.root = new N(obj, null);
};
ImmutableHelper.prototype.produce = function(mutator) {
    mutator(this.root.proxy);
    return this.root.raw();
};
